import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.CWgsre3x.js";const h=JSON.parse('{"title":"Υπεργολάβοι και διακανονισμοί","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/subcontractors.md","filePath":"el/plus/subcontractors.md"}'),r={name:"el/plus/subcontractors.md"};function s(i,a,c,n,p,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="υπεργολαβοι-και-διακανονισμοι" tabindex="-1">Υπεργολάβοι και διακανονισμοί <a class="header-anchor" href="#υπεργολαβοι-και-διακανονισμοι" aria-label="Permalink to &quot;Υπεργολάβοι και διακανονισμοί&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="αναθεση-εξωτερικου-προμηθευτη" tabindex="-1">Ανάθεση εξωτερικού προμηθευτή <a class="header-anchor" href="#αναθεση-εξωτερικου-προμηθευτη" aria-label="Permalink to &quot;Ανάθεση εξωτερικού προμηθευτή&quot;">​</a></h2><ol><li>Επιβεβαιώστε εγκεκριμένη σχέση, στοιχεία εταιρείας, επικοινωνία και εμπορικούς όρους. Ο εξωτερικός προμηθευτής διαφέρει από συνεργάτη που λαμβάνει προμήθεια.</li><li>Δημιουργήστε ή ελέγξτε τον υπεργολάβο στον εξουσιοδοτημένο χώρο. Επιλέξτε κράτηση, σωστό σκέλος και υπεργολάβο· ελέγξτε συμφωνημένο ποσό.</li><li>Καταγράψτε ανάθεση και ελέγξτε αποδοχή, απόρριψη ή ολοκλήρωση. Επιβεβαιώστε αποθηκευμένη κατάσταση και συντονίστε πρόγραμμα. Μην θεωρείτε ότι άλλαξε εσωτερική ανάθεση οδηγού ή άλλο σκέλος.</li><li>Επιλύστε συγκρούσεις και επιβεβαιώστε ορθότητα υπηρεσίας επιβάτη πριν από επιχειρησιακή απόφαση.</li></ol><h2 id="πληρωμες-προμηθευτη-και-κερδοφορια" tabindex="-1">Πληρωμές προμηθευτή και κερδοφορία <a class="header-anchor" href="#πληρωμες-προμηθευτη-και-κερδοφορια" aria-label="Permalink to &quot;Πληρωμές προμηθευτή και κερδοφορία&quot;">​</a></h2><p>Ελέγξτε εκκρεμείς υποχρεώσεις και εγγραφή ανάθεσης. Μόνο εξουσιοδοτημένοι διαχειριστές καταγράφουν διακανονισμούς και συμφωνία μέσω της υποστηριζόμενης ροής. Καταχωρίστε πραγματικό ποσό και μοναδική αναφορά· ελέγξτε υπόλοιπο. Διπλές αναφορές και υπερπληρωμές αποκλείονται. Η εγγραφή δεν αποδεικνύει εξωτερικό τραπεζικό έμβασμα.</p><p>Χρησιμοποιήστε την αναφορά κερδοφορίας για καταγεγραμμένα έσοδα και κόστος προμηθευτών. Δεν αποτελεί πλήρη λογιστική κατάσταση· συμφωνήστε με εγκεκριμένα οικονομικά στοιχεία. Δεν επιβεβαιώνεται αυτόνομη εξωτερική ανάθεση ή πληρωμή.</p><p>Δείτε <a href="/el/plus/commercial-partners.html">Εμπορικοί συνεργάτες</a> και <a href="/el/plus/payments-and-reconciliation.html">Πληρωμές</a>.</p>',8)])])}const _=e(r,[["render",s]]);export{h as __pageData,_ as default};
